const clean = (value, fallback, max=500, localize=true) => typeof value==='string' && value.trim() ? ((localize && LEGACY_COPY[value.trim()]) || value.trim()).slice(0,max) : fallback;
const escape = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeHref = value => typeof value==='string' && /^#[a-z][a-z\d_-]{0,40}$/i.test(value) ? value : '#contact';

export function normalizeSpec(input={}) {
  if (!input || typeof input!=='object' || Array.isArray(input)) input={};
  const style=STYLES.has(input.style)?input.style:'glass';
  const locale='en';
  const defaults=DEFAULT_SPEC;
  return {
    ...(['business','toy-store'].includes(input.pageType)?{pageType:input.pageType}:{}),
    brand:clean(input.brand,defaults.brand,80,false), tagline:clean(input.tagline,defaults.tagline,140),
    headline:clean(input.headline,defaults.headline,220), description:clean(input.description,defaults.description,800),
    ctaLabel:clean(input.ctaLabel,defaults.ctaLabel,60), secondaryCta:clean(input.secondaryCta,defaults.secondaryCta,60),
    email:typeof input.email==='string' && /^[^\s@<>"']{1,100}@[^\s@<>"']{1,150}\.[^\s@<>"']{2,30}$/.test(input.email) ? input.email : defaults.email,
    style, accent:typeof input.accent==='string' && /^#[a-f\d]{6}$/i.test(input.accent)?input.accent:ACCENTS[style], locale,
    services:Array.isArray(input.services)&&input.services.length ? input.services.slice(0,6).map((s,i)=>({title:clean(s?.title,defaults.services[i%defaults.services.length].title,100),description:clean(s?.description,defaults.services[i%defaults.services.length].description,500)})) : defaults.services.map(s=>({...s})),
    aboutTitle:clean(input.aboutTitle,defaults.aboutTitle,220), aboutText:clean(input.aboutText,defaults.aboutText,1000),
    nav:Array.isArray(input.nav)&&input.nav.length ? input.nav.slice(0,5).map((n,i)=>({label:clean(n?.label,defaults.nav[i%defaults.nav.length].label,50),href:safeHref(n?.href)})) : defaults.nav.map(n=>({...n})),
    footer:clean(input.footer,defaults.footer,300),
  };
}
function extractBrand(text) {
  const quoted=text.match(/(?:品牌(?:名|名称)?|公司(?:名|名称)?|名称|名为|叫做?|brand(?:\s+name)?|company(?:\s+name)?|named|called)\s*(?:是|为|[:：=])?\s*[“"「]([^”"」]{2,60})[”"」]/i);
  if(quoted)return quoted[1].trim();
  const forChinese=text.match(/(?:^|[，。；;\n]|(?:请|帮我|请帮我)\s*)[为给]\s*[“"「]?([A-Za-z0-9\u3400-\u9fff][A-Za-z0-9\u3400-\u9fff &._/-]{1,59}?)[”"」]?\s*(?:制作|设计|创建|搭建|做|建立|建设)/);
  const namedLatin=text.match(/(?:名为|叫做?|品牌名(?:称)?|公司名(?:称)?|brand(?:\s+name)?|company(?:\s+name)?|named|called)\s*(?:是|为|[:：=])?\s*([A-Za-z][A-Za-z0-9 &._/-]{1,59})/i);
  const namedChinese=text.match(/(?:名为|叫做?|品牌名(?:称)?|公司名(?:称)?)\s*(?:是|为|[:：=])?\s*([\u3400-\u9fff]{2,12}?)(?:的|[,，。；;\n]|$)/);
  const englishFor=text.match(/\bfor\s+([A-Z][A-Za-z0-9&./_-]*(?:\s+(?!(?:With|Using|In|The|A|An|Website|Site|Landing|That|Which|And|To)\b)[A-Z][A-Za-z0-9&./_-]*){0,3})/);
  const candidate=(forChinese?.[1]||englishFor?.[1]||namedLatin?.[1]||namedChinese?.[1]||'').split(/\.\s/)[0].trim().replace(/[.,;:]+$/,'');
  if(!candidate||/^(?:一家|一个|某个|企业|公司|咖啡店|网站|品牌|我的|我们|a\s|an\s|the\s|business\b|company\b|website\b)/i.test(candidate))return undefined;
  return candidate.slice(0,80);
}
export function createInitialSpec(prompt='',style='glass') {
  const text=String(prompt).slice(0,6000);
  // The workspace has a single English presentation language. Briefs may still
  // contain any language, and explicit user-authored brand names are preserved.
  const base={...DEFAULT_SPEC,style,accent:ACCENTS[style]||ACCENTS.glass};
  const business=/咖啡|coffee|café/i.test(text)?'coffee':/咨询公司|咨询企业|企业咨询|品牌咨询|战略咨询|\bconsulting\b|\bconsultancy\b|\badvisory\b/i.test(text)?'consulting':/设计工作室|设计公司|创意|工作室|视觉设计|品牌设计|\bstudio\b|creative|design agency/i.test(text)?'creative':/软件|科技|saas|software|platform|业务数据|自动化|工作流程|automation|automate|business data/i.test(text)?'software':'general';
  const variants={
    coffee:{brand:'Slowday',tagline:'Small rituals. Better days.',headline:'A little pause. A better kind of everyday.',description:'Thoughtfully sourced coffee, patiently crafted. A place to slow down, find your favorite cup and make a little more room for the good things.',ctaLabel:'Say hello',secondaryCta:'Discover our coffee',services:[{title:'Seasonal selections',description:'Distinctive coffees chosen for their character, thoughtfully roasted to let every origin speak.'},{title:'Your everyday ritual',description:'From your first espresso to a slow weekend pour-over. Find the cup that feels like you.'},{title:'Better, together',description:'Coffee for your team, your next event or your space. Let’s make something worth sharing.'}]},
    consulting:{brand:'North & Co.',tagline:'Perspective changes everything',headline:'Clarity for your next defining move.',description:'Independent thinking. Considered strategy. We work alongside ambitious teams to find a clearer direction and turn meaningful opportunities into action.',ctaLabel:'Start a conversation'},
    creative:{brand:'Form / Future',tagline:'Independent creative practice',headline:'Built to be felt. Made to stand apart.',description:'Strategy, identity and digital experiences for brands with something to say. We turn good ideas into a presence people remember.',ctaLabel:'Make something with us',secondaryCta:'Meet our practice'},
    software:{brand:'Orbit',tagline:'A more considered way to work',headline:'Less friction. More possibility.',description:'One clear space for the work that matters. Connect your team, simplify the everyday and make room for your next good idea.',ctaLabel:'Find your next step',secondaryCta:'Explore the possibilities'},
    general:{},
  };
  const brand=extractBrand(text);
  const businessServices={
    software:[{title:'Connected business data',description:'Bring scattered information into a clear workspace so your team can make sense of the work that matters.'},{title:'Thoughtful automation',description:'Simplify repetitive steps and keep useful information moving between the right people and processes.'},{title:'A shared team workspace',description:'Organize work around a common direction and give everyone a clearer view of what comes next.'}],
    consulting:[{title:'Strategy & positioning',description:'Understand the business, clarify the opportunity and define a direction your team can act on.'},{title:'Identity & experience',description:'Make the strategy tangible through a considered visual language and a connected digital experience.'},{title:'From direction to action',description:'Turn a shared ambition into practical next steps, working alongside your team as the work takes shape.'}],
    creative:[{title:'Brand identity',description:'A distinctive visual language that gives your ideas a clear and recognizable presence.'},{title:'Digital experiences',description:'Considered websites and interactions that make your brand easy to understand and enjoyable to use.'},{title:'Creative direction',description:'Turn a good idea into a coherent expression, with intention in every touchpoint and every detail.'}],
  };
  return normalizeSpec({...base,...variants[business],...(businessServices[business]?{services:businessServices[business]}:{}),...(brand?{brand}:{})});
}

