function toyBrick(x,y,width,height,color,columns=3,depth=22){
  const palettes={yellow:['#f8c93d','#ffe47c','#d49b18'],red:['#ec5844','#ff8c72','#ba352b'],blue:['#568fb6','#8ab8d1','#326b91'],cream:['#f4eed9','#fffaf0','#d4cbb1'],green:['#6f9475','#9cb59c','#4d7255']};
  const [front,top,side]=palettes[color]||palettes.yellow;
  const studs=Array.from({length:columns},(_,i)=>`<ellipse cx="${x+width*(i+.5)/columns+depth*.5}" cy="${y-depth*.28-2}" rx="${Math.min(9,width/columns*.24)}" ry="4" fill="${side}"/><ellipse cx="${x+width*(i+.5)/columns+depth*.5}" cy="${y-depth*.28-5}" rx="${Math.min(9,width/columns*.24)}" ry="4" fill="${top}"/>`).join('');
  return `<g><path d="M${x} ${y}h${width}v${height}h-${width}Z" fill="${front}"/><path d="m${x} ${y} ${depth} -${depth*.55}h${width}l-${depth} ${depth*.55}Z" fill="${top}"/><path d="m${x+width} ${y} ${depth} -${depth*.55}v${height}l-${depth} ${depth*.55}Z" fill="${side}"/>${studs}<path d="M${x+4} ${y+height-3}h${width-8}" stroke="${side}" opacity=".25"/></g>`;
}
