function clientScript({preview,projectId,zh}){
  const messages={sending:'Sending…',success:'Your message is saved. Thank you for reaching out.',error:'We couldn’t send your message. Please try again.',timeout:'The preview did not respond. Please try again.',previewNoProject:'This is a style sample. Create a project first to test saving a real enquiry.'};
  return `(()=>{const settings=${JSON.stringify({preview,projectId,messages}).replace(/</g,'\\u003c')};const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});const form=document.querySelector('.contact-form'),status=document.querySelector('.form-status'),button=form.querySelector('button[type="submit"]'),label=button.innerHTML;let pending=null;function done(ok,error){clearTimeout(pending?.timer);pending=null;button.disabled=false;button.innerHTML=label;status.className='form-status '+(ok?'success':'error');status.textContent=ok?settings.messages.success:(error||settings.messages.error);if(ok)form.reset()}window.addEventListener('message',event=>{if(!settings.preview||event.source!==parent||event.data?.type!=='biznova:lead-result'||!pending||event.data.requestId!==pending.id)return;done(!!event.data.ok,event.data.error)});form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity()||pending)return;const values=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent=settings.messages.sending;status.className='form-status';status.textContent='';if(settings.preview&&!settings.projectId){done(false,settings.messages.previewNoProject);return}if(settings.preview&&parent!==window){const id=String(Date.now())+'-'+Math.random().toString(36).slice(2);pending={id,timer:setTimeout(()=>done(false,settings.messages.timeout),12000)};parent.postMessage({type:'biznova:lead',projectId:settings.projectId,requestId:id,payload:values},'*');return}try{const endpoint=settings.preview?'/api/studio/projects/'+encodeURIComponent(settings.projectId)+'/leads':'/api/leads';const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const body=await response.json();done(response.ok,body.error)}catch{done(false)}})})();`;
}

